fit_expected<Eigen::VectorXd> lavaan_ml_start_values(
    const spec::LatentStructure& pt, const model::MatrixRep& rep,
    const SampleStats& sample, const spec::Starts& hints, bool simple) {
  if (auto ok = supported(pt); !ok) return std::unexpected(ok.error());
  // Rows sharing a free slot would otherwise take the last row's start.
  if (auto ok = linear_supported(pt); !ok) return std::unexpected(ok.error());
  if (sample.S.size() != ix(pt.n_groups()) || rep.cell_for_row.size() != pt.size())
    return std::unexpected(invalid("lavaan starts: sample/model block mismatch"));
  auto fabin = fabin_start_values(pt, rep, sample, {}, FabinVariant::Fabin3, true);
  if (!fabin) return std::unexpected(fabin.error());
  Eigen::VectorXd start = Eigen::VectorXd::Zero(pt.n_free());
  // Observed exogenous variables are regression predictors with no incoming
  // paths. A covariance-only model has no exogenous predictor block.
  std::vector<std::vector<bool>> exogenous(ix(pt.n_groups()), std::vector<bool>(ix(pt.n_vars), false));
  for (std::size_t i = 0; i < pt.size(); ++i)
    if (pt.group[i] > 0 && pt.op[i] == parse::Op::Regression)
      exogenous[ix(pt.group[i] - 1)][ix(pt.rhs_var[i])] = true;
  for (std::size_t i = 0; i < pt.size(); ++i) {
    if (pt.group[i] <= 0) continue;
    if (pt.op[i] == parse::Op::Measurement) exogenous[ix(pt.group[i] - 1)][ix(pt.rhs_var[i])] = false;
    if (pt.op[i] == parse::Op::Regression) exogenous[ix(pt.group[i] - 1)][ix(pt.lhs_var[i])] = false;
  }
  for (std::size_t i = 0; i < pt.size(); ++i) {
    if (pt.free[i] <= 0 || pt.group[i] <= 0) continue;
    const auto k = pt.free[i] - 1;
    const auto b = ix(pt.group[i] - 1);
    const int l = pt.lhs_var[i], r = pt.rhs_var[i];
    const int lo = observed(pt, l), ro = observed(pt, r);
    if (pt.op[i] == parse::Op::Measurement) {
      start(k) = simple ? 0.7 : latent(pt, r) ? 1.0 : (*fabin)(k);
      // A factor with mixed observed/latent indicators skips FABIN altogether.
      if (!simple) for (std::size_t j = 0; j < pt.size(); ++j)
        if (pt.group[j] == pt.group[i] && pt.op[j] == parse::Op::Measurement &&
            pt.lhs_var[j] == l && latent(pt, pt.rhs_var[j])) start(k) = 1.0;
    } else if (pt.op[i] == parse::Op::Covariance) {
      if (l == r) start(k) = simple ? 1.0 : lo >= 0 ? 0.5 * sample.S[b](lo, lo) : 0.05;
      if (!simple && lo >= 0 && ro >= 0 && exogenous[b][ix(l)] && exogenous[b][ix(r)])
        start(k) = sample.S[b](lo, ro);
    } else if (!simple && pt.op[i] == parse::Op::Intercept && lo >= 0 && b < sample.mean.size())
      start(k) = sample.mean[b](lo);
  }
  if (!simple && std::none_of(pt.is_user_latent.begin(), pt.is_user_latent.end(), [](auto x) { return x != 0; })) {
    // Covariance-regression identities: beta=Sxx^-1 Sxy, residual variance
    // Syy-beta'Sxy, intercept ybar-beta'xbar. Fixed slopes do not alter this
    // initializer; explicit hints are applied after it, as in the oracle.
    for (std::size_t b = 0; b < sample.S.size(); ++b) for (int y : pt.ov_order) {
      std::vector<std::size_t> rows;
      for (std::size_t i = 0; i < pt.size(); ++i)
        if (pt.group[i] == static_cast<int>(b + 1) && pt.op[i] == parse::Op::Regression && pt.lhs_var[i] == y)
          rows.push_back(i);
      if (rows.empty()) continue;
      const Eigen::Index n = static_cast<Eigen::Index>(rows.size());
      Eigen::MatrixXd xx(n, n);
      Eigen::VectorXd xy(n), means = Eigen::VectorXd::Zero(n);
      const int yo = observed(pt, y);
      for (Eigen::Index j = 0; j < n; ++j) {
        const int x = observed(pt, pt.rhs_var[rows[ix(j)]]);
        xy(j) = sample.S[b](x, yo);
        if (b < sample.mean.size()) means(j) = sample.mean[b](x);
        for (Eigen::Index k = 0; k < n; ++k)
          xx(j, k) = sample.S[b](x, observed(pt, pt.rhs_var[rows[ix(k)]]));
      }
      Eigen::LDLT<Eigen::MatrixXd> ldlt(xx);
      Eigen::VectorXd beta = Eigen::VectorXd::Zero(n);
      if (ldlt.info() == Eigen::Success && ldlt.isPositive()) beta = ldlt.solve(xy);
      for (Eigen::Index j = 0; j < n; ++j) {
        auto i = rows[ix(j)];
        if (pt.free[i] > 0) start(pt.free[i] - 1) = beta(j);
      }
      const double residual = sample.S[b](yo, yo) - beta.dot(xy);
      for (std::size_t i = 0; i < pt.size(); ++i) {
        if (pt.group[i] != static_cast<int>(b + 1) || pt.lhs_var[i] != y || pt.free[i] <= 0) continue;
        if (pt.op[i] == parse::Op::Covariance && pt.rhs_var[i] == y &&
            residual > 0.001 * sample.S[b](yo, yo) && residual < 0.999 * sample.S[b](yo, yo))
          start(pt.free[i] - 1) = residual;
        if (pt.op[i] == parse::Op::Intercept && b < sample.mean.size())
          start(pt.free[i] - 1) = sample.mean[b](yo) - beta.dot(means);
      }
    }
  }
  // An exogenous single-indicator latent starts with variance max(Sii-theta, .05).
  // As in the oracle, a latent is endogenous when it is regressed on anything
  // or is itself an indicator of another latent (a first-order factor of a
  // higher-order model). theta is the indicator residual's user value: its
  // fixed value, else its start hint, else 1.
  if (!simple) for (std::size_t i = 0; i < pt.size(); ++i) {
    if (pt.op[i] != parse::Op::Covariance || pt.lhs_var[i] != pt.rhs_var[i] ||
        !latent(pt, pt.lhs_var[i]) || pt.free[i] <= 0) continue;
    const int v = pt.lhs_var[i];
    int indicator = -1, count = 0;
    bool endogenous = false;
    for (std::size_t j = 0; j < pt.size(); ++j) {
      if (pt.group[j] != pt.group[i]) continue;
      if (pt.op[j] == parse::Op::Measurement && pt.rhs_var[j] == v) endogenous = true;
      if (pt.lhs_var[j] != v) continue;
      if (pt.op[j] == parse::Op::Regression) endogenous = true;
      if (pt.op[j] == parse::Op::Measurement) { indicator = pt.rhs_var[j]; ++count; }
    }
    if (endogenous || count != 1 || observed(pt, indicator) < 0) continue;
    double theta = 1.0;
    for (std::size_t j = 0; j < pt.size(); ++j) {
      if (pt.group[j] != pt.group[i] || pt.op[j] != parse::Op::Covariance ||
          pt.lhs_var[j] != indicator || pt.rhs_var[j] != indicator) continue;
      if (pt.free[j] == 0 && std::isfinite(pt.fixed_value[j])) theta = pt.fixed_value[j];
      else if (pt.free[j] > 0 && ix(pt.free[j] - 1) < hints.hint.size() &&
               std::isfinite(hints.hint[ix(pt.free[j] - 1)]))
        theta = hints.hint[ix(pt.free[j] - 1)];
    }
    const int o = observed(pt, indicator);
    start(pt.free[i] - 1) = std::max(sample.S[ix(pt.group[i] - 1)](o, o) - theta, 0.05);
  }
  for (Eigen::Index k = 0; k < start.size() && ix(k) < hints.hint.size(); ++k)
    if (std::isfinite(hints.hint[ix(k)])) start(k) = hints.hint[ix(k)];
  if (!start.allFinite()) return std::unexpected(invalid("lavaan starts are nonfinite"));
  return start;
}

fit_expected<double> lavaan_acceptance_gradient(spec::LatentStructure pt,
    const model::MatrixRep& rep, const SampleStats& sample,
    const Eigen::VectorXd& theta, const Bounds& bounds,
    const Eigen::VectorXd& scale) {
  if (auto ok = resolve_fixed_x_from_sample(pt, rep, sample); !ok) return std::unexpected(ok.error());
  auto ev = model::ModelEvaluator::build(pt, rep);
  if (!ev) return std::unexpected(invalid(ev.error().detail));
  auto prob = ml_objective(*ev, sample);
  if (!prob) return std::unexpected(prob.error());
  const Eigen::VectorXd s = scale.size() ? scale : Eigen::VectorXd::Ones(theta.size());
  if (s.size() != theta.size() || (!bounds.empty() &&
      (bounds.lower.size() != theta.size() || bounds.upper.size() != theta.size())))
    return std::unexpected(invalid("lavaan acceptance gradient: dimension mismatch"));
  Eigen::VectorXd g;
  const double inf = std::numeric_limits<double>::infinity();
  if (!std::isfinite(prob->f(theta, g)) || g.size() != theta.size()) return inf;
  auto coordinates = lavaan_ml_coordinates(pt);
  if (!coordinates) return std::unexpected(coordinates.error());
  if (coordinates->active()) {
    const Eigen::VectorXd reduced = coordinates->Kmat.transpose() * g.cwiseQuotient(s);
    return reduced.size() ? reduced.cwiseAbs().maxCoeff() : 0.0;
  }
  double out = 0.0;
  for (Eigen::Index j = 0; j < theta.size(); ++j) {
    // The oracle skips coordinates exactly at either bound. A coordinate
    // round trip may move theta by a few ulps, so equality is relative here.
    auto at = [&](double b) {
      return std::isfinite(b) && std::abs(theta(j) - b) <=
          8 * std::numeric_limits<double>::epsilon() * std::max(1.0, std::abs(b));
    };
    if (!bounds.empty() && (at(bounds.lower(j)) || at(bounds.upper(j)))) continue;
    const double gz = g(j) / s(j);
    if (!std::isfinite(gz)) return inf;
    out = std::max(out, std::abs(gz));
  }
  return out;
}

